#!/usr/bin/env bash
# -----------------------------------------------------------------------------
# run.sh — the one entry point to build and run this workspace.
#
# GENERATED by micro-os-scaffold from scaffold.json (new source layout: the
# harness is micro-os-plus-iii/tests/). Tool paths come from scripts/env.sh.
#
#   ./run.sh                  build, then run the selected tests
#   ./run.sh build            configure and build only
#   ./run.sh test [name ...]  build, then run CTest
#   ./run.sh list             list the CTest cases (* = selected, L = local)
#   ./run.sh all              build, then run every case, hardware included
#   ./run.sh clean            remove this configuration's build tree
#
# Options:
#   -c, --config NAME   configuration (default: 'aarch64-rpi-zero-2w-cmake-gcc-debug')
#   --no-build          do not build before running
#   --hwd               include the hardware (-hwd) cases
#   --hwd-only          run only the hardware (-hwd) cases
#   -R, --regex RE      ad-hoc CTest regular expression
#   -v, --verbose       verbose CTest output
#   -h, --help          this text
#
# A name is a test directory (mtp-example), a full CTest name
# (cortexm-weactf411-mtp-example-hwd), or a selection id (scaffold.json).
#
# This script never runs `xpm link`: it links the workspace's own copies of
# the port and device packages into build/<configuration>/xpacks/ itself, so
# the machine-wide xpm registrations are not changed.
#
# Hardware cases: CTest runs OpenOCD with the platform's openocd.cfg. Probe
# selection: PROBE=jlink|olimex|cmsis-dap (AArch Pi boards),
# UOS_HW_ADAPTER_SERIAL=<serial> (several CMSIS-DAP probes),
# UOS_HW_ADAPTER_KHZ=<kHz>.
#
# Results are files too:
#   <build>/ctest.xml            the CTest JUnit summary
#   <build>/ctest.log            the full CTest output
#   <build>/.../<app>.tap        the complete µTest++ TAP report (mtp-* tests)
# -----------------------------------------------------------------------------
set -uo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TESTS="$HERE/micro-os-plus-iii/tests"
source "$HERE/scripts/env.sh"

DEFAULT_CONFIG='aarch64-rpi-zero-2w-cmake-gcc-debug'
CONFIGS=('aarch64-rpi-zero-2w-cmake-gcc-debug')
CMD=""
CONFIG=""
NO_BUILD=0
HWD=0
VERBOSE=0
REGEX=""
WANTED=()

usage() {
  sed -n '2,40p' "$0"
  exit 0
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    -h|--help) usage ;;
    -c|--config)
      [[ $# -ge 2 ]] || { echo "--config needs a value" >&2; exit 2; }
      CONFIG="$2"
      shift
      ;;
    --no-build) NO_BUILD=1 ;;
    --hwd) HWD=1 ;;
    --hwd-only) HWD=2 ;;
    --all) CMD="all" ;;
    --list) CMD="list" ;;
    --clean) CMD="clean" ;;
    -v|--verbose) VERBOSE=1 ;;
    -R|--regex)
      [[ $# -ge 2 ]] || { echo "--regex needs a value" >&2; exit 2; }
      REGEX="$2"
      shift
      ;;
    build|test|list|clean|all) CMD="$1" ;;
    -*) echo "Unknown option: $1 (try --help)" >&2; exit 2 ;;
    *) WANTED+=("$1") ;;
  esac
  shift
done

CMD="${CMD:-test}"
CONFIG="${CONFIG:-$DEFAULT_CONFIG}"

# Per configuration: the platform, the build type, the toolchain file, the
# packages to link (xpack name : workspace folder), the pinned tool folders,
# and the selected tests (directory names).
PLATFORM=""
BUILD_TYPE="Debug"
TOOLCHAIN=""
PACKAGES=()
TOOL_DIRS=()
BUILD_XPACKS=()
SELECTED_APPS=()
case "$CONFIG" in
  'aarch64-rpi-zero-2w-cmake-gcc-debug')
    PLATFORM='aarch64-rpi-zero-2w'
    BUILD_TYPE='Debug'
    TOOLCHAIN='aarch64-none-elf-gcc.cmake'
    PACKAGES=('micro-os-plus-iii-aarch64:aarch64/micro-os-plus-iii-aarch64' 'micro-os-plus-iii-devices-storage:common/micro-os-plus-iii-devices-storage' 'micro-os-plus-iii-devices-bcm283x:common/micro-os-plus-iii-devices-bcm283x')
    TOOL_DIRS=('/home/dan/.local/xPacks/@xpack-dev-tools/aarch64-none-elf-gcc/15.2.1-1.1.1/.content/bin' '/home/dan/.local/xPacks/@xpack-dev-tools/qemu-arm/9.2.4-1.1/.content/bin' '/home/dan/.local/xPacks/@xpack-dev-tools/openocd/0.12.0-7.1/.content/bin' '/home/dan/.local/xPacks/@xpack-dev-tools/cmake/3.26.5-1.1/.content/bin' '/home/dan/.local/xPacks/@xpack-dev-tools/ninja-build/1.11.1-3.1/.content/bin')
    BUILD_XPACKS=()
    SELECTED_APPS=('smp-mat-test' 'mtp-example' 'mtp-args' 'mtp-smp')
    ;;
  *)
    echo "Unknown configuration: $CONFIG" >&2
    echo "Known: ${CONFIGS[*]}" >&2
    exit 2
    ;;
esac

BUILD_REL="build/$CONFIG"
BUILD_DIR="$TESTS/$BUILD_REL"

link_dependencies() {
  # The packages: build/<C>/xpacks/@micro-os-plus/<name> -> the workspace's
  # copy, relative, so the workspace can be moved.
  mkdir -p "$BUILD_DIR/xpacks/@micro-os-plus" "$BUILD_DIR/xpacks/@xpacks" "$BUILD_DIR/xpacks/.bin"
  local pair name dir
  for pair in "${PACKAGES[@]}"; do
    name="${pair%%:*}"
    dir="${pair#*:}"
    ln -sfn "../../../../../../$dir" "$BUILD_DIR/xpacks/@micro-os-plus/$name"
  done
  # Per-configuration libraries the platform takes from the build folder
  # (arm-cmsis): from the xPack store, found by the scaffolder.
  local lib var target
  for pair in "${BUILD_XPACKS[@]}"; do
    lib="${pair%%:*}"
    var="${pair#*:}"
    target="${!var:-}"
    if [[ -n "$target" && -d "$target" ]]; then
      ln -sfn "$target" "$BUILD_DIR/xpacks/$lib"
    else
      echo "warning: $lib not found (set $var); the configure step may fail" >&2
    fi
  done
  # The configuration's pinned tools, where its CMake looks for them
  # (QEMU through a HINTS on xpacks/.bin) and on PATH (OpenOCD, compilers).
  local tool_dir tool
  for tool_dir in "${TOOL_DIRS[@]}"; do
    [[ -d "$tool_dir" ]] || continue
    for tool in "$tool_dir"/*; do
      [[ -x "$tool" && ! -d "$tool" ]] && ln -sfn "$tool" "$BUILD_DIR/xpacks/.bin/$(basename "$tool")"
    done
  done
  export PATH="$BUILD_DIR/xpacks/.bin:$PATH"
}

configure_and_build() {
  # A build tree moved with the workspace keeps absolute paths in its CMake
  # cache: start it again.
  if [[ -f "$BUILD_DIR/CMakeCache.txt" ]]; then
    local cached_dir
    cached_dir="$(sed -n 's/^CMAKE_CACHEFILE_DIR:INTERNAL=//p' "$BUILD_DIR/CMakeCache.txt" | head -n 1)"
    if [[ "$cached_dir" != "$BUILD_DIR" ]]; then
      echo "== build tree was moved from ${cached_dir:-another folder}; reconfiguring"
      rm -rf "$BUILD_DIR"
    fi
  fi
  link_dependencies

  local args=(-S . -B "$BUILD_REL" -G Ninja
              -D "CMAKE_BUILD_TYPE=$BUILD_TYPE" -D "PLATFORM_NAME=$PLATFORM")
  [[ -n "$TOOLCHAIN" ]] && args+=(-D "CMAKE_TOOLCHAIN_FILE=xpacks/@micro-os-plus/build-helper/cmake/toolchains/$TOOLCHAIN")
  # Extra CMake options, e.g. UOS_CMAKE_ARGS='-DFOO=1' ./run.sh build
  if [[ -n "${UOS_CMAKE_ARGS:-}" ]]; then
    eval "_extra=(${UOS_CMAKE_ARGS})"
    args+=("${_extra[@]}")
  fi

  echo "== configure $CONFIG (platform=$PLATFORM, build=$BUILD_TYPE)"
  (cd "$TESTS" && cmake "${args[@]}") || exit $?
  echo "== build $CONFIG"
  (cd "$TESTS" && cmake --build "$BUILD_REL" -- -k 0) || exit $?
}

registered() {
  ctest --test-dir "$BUILD_DIR" -N \
    | sed -n 's/^ *Test *#[0-9]*: *\([^ ]*\).*/\1/p'
}

# The test cases, without the fixtures CTest adds by itself
# (<case>-reset, <case>-sd-make, <case>-sd-remove).
cases_of() {
  grep -vE -- '-(reset|sd-make|sd-remove)$' <<< "$REGISTERED" || true
}

# A selection id, as recorded in scaffold.json.
selection_names() {
  case "$CONFIG:$1" in
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.1') printf '%s\n' 'usb_test' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.2') printf '%s\n' 'wifi-net' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.3') printf '%s\n' 'wifi-tcp-server' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.4') printf '%s\n' 'smp_test0' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.5') printf '%s\n' 'smp_test1' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.6') printf '%s\n' 'smp_test2' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.7') printf '%s\n' 'smp_test3' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.8') printf '%s\n' 'smp_test4' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.9') printf '%s\n' 'smp-num-test' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.10') printf '%s\n' 'smp-pipeline-test' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.11') printf '%s\n' 'smp-pro-cons-test' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.12') printf '%s\n' 'smp-mat-test' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.13') printf '%s\n' 'sd_test' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.14') printf '%s\n' 'smp-mat-sdcard-test' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.15') printf '%s\n' 'clock-test' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.16') printf '%s\n' 'mutex-stress' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.17') printf '%s\n' 'rtos-apis' ;;
    'aarch64-rpi-zero-2w-cmake-gcc-debug:5.18') printf '%s\n' 'cmsis-os-validator' ;;
    *) ;;
  esac
}

# A test directory name, or an exact CTest name.
application_names() {
  local wanted="$1" name
  if grep -qx -- "$wanted" <<< "$CASES"; then
    echo "$wanted"
    return
  fi
  while IFS= read -r name; do
    case "$name" in
      "$PLATFORM-$wanted-qemu"|"$PLATFORM-$wanted-hwd"|"$PLATFORM-$wanted-host"|"$PLATFORM-$wanted") echo "$name" ;;
    esac
  done <<< "$CASES"
}

if [[ "$CMD" == "clean" ]]; then
  rm -rf "$BUILD_DIR"
  echo "Removed $BUILD_DIR"
  exit 0
fi

if [[ "$NO_BUILD" == "0" ]]; then
  configure_and_build
else
  link_dependencies
fi
[[ -d "$BUILD_DIR" ]] || {
  echo "No build tree: $BUILD_DIR (run ./run.sh build)" >&2
  exit 2
}

REGISTERED="$(registered)"
CASES="$(cases_of)"

# The default selection: the scaffolded tests, then the local ones
# (scripts/local-tests.txt, owned by the user).
SELECTED=()
for app in "${SELECTED_APPS[@]}"; do
  while IFS= read -r name; do [[ -n "$name" ]] && SELECTED+=("$name"); done <<< "$(application_names "$app")"
done
LOCAL=()
LOCAL_TESTS="$HERE/scripts/local-tests.txt"
if [[ -f "$LOCAL_TESTS" ]]; then
  while IFS= read -r line; do
    line="${line%%#*}"
    read -r first _ <<< "$line" || true
    [[ -z "${first:-}" || "$first" == "keep" ]] && continue
    first="${first##*/}"
    while IFS= read -r name; do
      [[ -n "$name" ]] && { LOCAL+=("$name"); SELECTED+=("$name"); }
    done <<< "$(application_names "$first")"
  done < "$LOCAL_TESTS"
fi

if [[ "$CMD" == "build" ]]; then
  exit 0
fi

if [[ "$CMD" == "list" ]]; then
  echo "CTest cases of $CONFIG (* = selected, L = local):"
  while IFS= read -r name; do
    [[ -n "$name" ]] || continue
    mark=" "
    for selected in "${SELECTED[@]}"; do [[ "$name" == "$selected" ]] && mark="*"; done
    for local_name in "${LOCAL[@]}"; do [[ "$name" == "$local_name" ]] && mark="L"; done
    echo "  $mark $name"
  done <<< "$CASES"
  exit 0
fi

# ---------------------------------------------------------------------------
# Which cases.
NAMES=()
if [[ ${#WANTED[@]} -gt 0 ]]; then
  for wanted in "${WANTED[@]}"; do
    found="$(selection_names "$wanted")"
    if [[ -n "$found" ]]; then
      found="$(application_names "$found")"
    else
      found="$(application_names "$wanted")"
    fi
    if [[ -z "$found" ]]; then
      echo "No test '$wanted' in $CONFIG." >&2
      echo "Try: ./run.sh list" >&2
      exit 2
    fi
    while IFS= read -r name; do
      [[ -n "$name" ]] && NAMES+=("$name")
    done <<< "$found"
  done
elif [[ "$CMD" == "all" ]]; then
  while IFS= read -r name; do
    [[ -n "$name" ]] && NAMES+=("$name")
  done <<< "$CASES"
else
  NAMES=("${SELECTED[@]}")
  [[ ${#NAMES[@]} -gt 0 ]] || {
    echo "No selected tests for $CONFIG: use 'all', or name a test." >&2
    exit 2
  }
fi

# Hardware cases need the board and the probe: skip them unless asked for,
# except when there is nothing else to run.
if [[ "$HWD" == "2" ]]; then
  RUN=()
  for name in "${NAMES[@]}"; do
    [[ "$name" == *-hwd ]] && RUN+=("$name")
  done
  if [[ ${#RUN[@]} -eq 0 ]]; then
    echo "No hardware (-hwd) case among: ${NAMES[*]}" >&2
    exit 2
  fi
  NAMES=("${RUN[@]}")
elif [[ "$HWD" == "0" && "$CMD" != "all" ]]; then
  RUN=()
  for name in "${NAMES[@]}"; do
    [[ "$name" == *-hwd ]] || RUN+=("$name")
  done
  if [[ ${#RUN[@]} -eq 0 ]]; then
    RUN=("${NAMES[@]}")
    echo "Only hardware (-hwd) cases match: the board and the probe must be connected."
  fi
  NAMES=("${RUN[@]}")
fi

if [[ -n "$REGEX" ]]; then
  PATTERN="$REGEX"
else
  PATTERN=""
  for name in "${NAMES[@]}"; do
    escaped="$(sed 's/[][\.^$*+?(){}|]/\\&/g' <<< "$name")"
    PATTERN="${PATTERN:+$PATTERN|}$escaped"
  done
  PATTERN="^(${PATTERN})$"
fi

JUNIT=()
if ctest --help 2>&1 | grep -- '--output-junit' > /dev/null; then
  JUNIT=(--output-junit "$BUILD_DIR/ctest.xml")
fi
ARGS=(--test-dir "$BUILD_DIR" --output-on-failure "${JUNIT[@]}" -R "$PATTERN")
[[ "$VERBOSE" == "1" ]] && ARGS+=(-V)

echo "== run ${#NAMES[@]} case(s) of $CONFIG"
ctest "${ARGS[@]}"
status=$?
if [[ -f "$BUILD_DIR/Testing/Temporary/LastTest.log" ]]; then
  cp "$BUILD_DIR/Testing/Temporary/LastTest.log" "$BUILD_DIR/ctest.log"
  echo "   Full CTest log: $BUILD_DIR/ctest.log"
fi
exit "$status"
